from PIL import Image
def image_dimensions(html):
 def annotate(match):
  tag=match[0];src=re.search(r'src="/assets/([^"?]+)',tag)
  if src and 'width=' not in tag:
   width,height=Image.open(DIST/'assets'/src[1]).size
   tag=tag.replace('<img ',f'<img width="{width}" height="{height}" ',1)
  return tag
 return re.sub(r'<img\b[^>]+>',annotate,html)
