def casecard(c,featured=False):
 return f'''<article class="portfolio-case {'case-featured' if featured else ''}"><a class="case-cover {c['id']}" href="/portfolio/{c['id']}/" aria-label="Conhecer o projeto {c['name']}"><img src="/assets/{c['image']}" alt="{escape(c['name'])}: imagem do projeto." loading="lazy"><span class="case-cover-action">Conhecer o projeto {ARROW}</span></a><div class="case-intro"><h3><a href="/portfolio/{c['id']}/">{c['name']}</a></h3><p class="project-discipline">{c['discipline']}</p><p>{c['description']}</p><p class="case-result"><strong>{c['metric']}</strong><span>{c['context']}</span></p><a class="text-link" href="/portfolio/{c['id']}/">Ver resultados e minha participação {ARROW}</a></div></article>'''
def write_case(c):
 path=f"/portfolio/{c['id']}/"
 content=head(c['name']+' · Portfólio de Julia Maschietto',c['description'],path)+'<body class="portfolio-page case-page">'+CONTRACT+nav(True)+'<main id="conteudo"><div class="wrap case-document"><a class="text-link case-back" href="/portfolio/#cases"><span class="icon i-arrow" aria-hidden="true"></span> Voltar aos projetos</a>'
 content+=f'<header class="case-heading"><h1>{c["title"]}</h1><p class="project-discipline">{c["discipline"]}</p><p class="case-lead">{c["lead"]}</p></header>'
 if c.get('opening'):content+=imgfigure(c['opening'],c['caption'],c['caption'],'case-opening '+c['id'])
 participation='<section class="case-participation" aria-labelledby="participation-title"><h2 id="participation-title">Minha <em>participação.</em></h2>'+scope(c['roles'])+'</section>'
 result=f'<section class="case-results" aria-labelledby="results-title"><h2 id="results-title">Resultados <em>e registros.</em></h2><p>{c["result"]}</p>'
 if c['id']=='bruna':
  content+='<div class="case-bruna-grid"><div>'+participation+result+'</section></div><div class="evidence-gallery">'+c['gallery']()+'</div></div>'
 else:
  content+=participation+result+f'<div class="evidence-gallery">{c["gallery"]()}</div></section>'
 content+='<section class="case-credits" aria-labelledby="credits-title"><h2 id="credits-title">Créditos do projeto</h2>'+scope(c['credits'])+(f'<p class="campaign-identification">{c["legal"]}</p>' if c.get('legal') else '')+'</section>'
 index=CASES.index(c);n=CASES[(index+1)%len(CASES)]
 content+=f'<a class="case-next" href="/portfolio/{n["id"]}/"><span>Próximo projeto</span><strong>{n["name"]}</strong>{ARROW}</a></div>'+footer()
 dest=DIST/path.strip('/');dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(image_dimensions(content),encoding='utf-8')
hero=re.search(r'  <section class="hero outer-frame"[\s\S]*?</section>',commercial)[0]
hero=absolute_assets(hero).replace('Estratégia para posicionar.<br> <em>Criatividade para comunicar.</em>','Branding e posicionamento.<br> <em>Direção criativa.</em>').replace('Defino o que sua marca precisa dizer e transformo esse posicionamento em conteúdo, campanhas e direção criativa.','Julia Maschietto. Fundadora e Estrategista de Marca da [RE]VERSA.').replace('href="#projetos"','href="#cases"')
hero=re.sub(r'href="https://wa.me/[^\"]+"',f'href="{WA}"',hero)
about=re.search(r'  <section class="about section wrap"[\s\S]*?</section>',commercial)[0]
